/**
 * EDR-121 S2: collect what a host is (services, software, users/logons, usage) — deterministic, no LLM.
 *  - every host: Wazuh inventory (wazuh-states-inventory-*), vulnerabilities, SCA, alerts (aggregations only, never raw logs)
 *  - SSH hosts: one fixed read-only script (never generated by the AI)
 * Every fact carries an evidence id (port:tcp/443, svc:<name>, pkg:<name>, user:<name>, proc:<name>, conn:<ip>, ext:<name>, unit:<name>, cron:<n>, ctr:<name>)
 * so the AI can only cite things that exist.
 */
import type { Ctx } from "../api/context.js";
import { indexer, managerApi } from "../api/context.js";
import { sshExec } from "../ssh/index.js";

export interface ListenFact { id: string; proto: string; port: number; local_ip: string; exposure: "local" | "lan" | "all" | "internet"; process: string | null; pid: number | null; service: string | null; known: string | null }
export interface UserFact { id: string; name: string; type: string; admin: boolean; groups: string[]; shell?: string | null; disabled?: boolean | null; last_logon?: string | null; logons_7d?: number; failures_7d?: number; logon_types?: Record<string, number>; sources?: string[] }
export interface Facts {
  version: 1;
  collected_at: string;
  host: { id: number; name: string; kind: string; os_family: string | null; os: string | null; agent_id: string | null; agent_status: string | null; agent_last_seen: string | null; address: string; environment: string };
  system: { hostname?: string | null; os?: string | null; kernel?: string | null; arch?: string | null; cpu?: string | null; cores?: number | null; memory_gb?: number | null; serial?: string | null; ips: string[]; has_public_ip: boolean };
  listening: ListenFact[];
  services: { id: string; name: string; display?: string | null; start_type?: string | null; state: string; pid?: number | null }[];
  services_total: number;
  software: { total: number; items: { id: string; name: string; version: string | null; vendor: string | null; installed: string | null }[]; hotfixes: number; latest_hotfixes: string[]; browser_extensions: { id: string; name: string; browser: string | null; version: string | null; enabled: boolean | null; from_store: boolean | null }[] };
  users: UserFact[];
  processes: { id: string; name: string; count: number; sample_cmd: string | null }[];
  processes_total: number;
  connections: { id: string; remote_ip: string; remote_port: number | null; process: string | null; count: number }[];
  activity: { heatmap: number[][]; total_7d: number; top_rules: { id: string; description: string; level: number; count: number }[] };
  vulns: { total: number; by_severity: Record<string, number>; top_packages: { name: string; count: number; critical: number }[] };
  sca: { policy: string; score: number; pass: number; fail: number }[];
  ssh?: { ok: boolean; error?: string; listen: { proto: string; port: number; local_ip: string; process: string | null; pid: number | null }[]; units: { id: string; name: string }[]; logged_in: string[]; last_logins: string[]; cron: { id: string; line: string }[]; timers: string[]; containers: { id: string; name: string; image: string; ports: string }[]; web: string[]; admins: string[]; pack_rev?: number | null };
  limits: Record<string, string>;
}

const WELL_KNOWN: Record<number, string> = {
  20: "FTP data", 21: "FTP", 22: "SSH", 23: "Telnet", 25: "SMTP", 53: "DNS", 67: "DHCP", 80: "HTTP", 88: "Kerberos", 110: "POP3", 111: "rpcbind", 123: "NTP",
  135: "Windows RPC", 137: "NetBIOS", 138: "NetBIOS", 139: "NetBIOS/SMB", 143: "IMAP", 161: "SNMP", 389: "LDAP", 443: "HTTPS", 445: "SMB（ファイル共有）", 464: "Kerberos パスワード",
  465: "SMTPS", 500: "IKE/VPN", 514: "syslog", 587: "SMTP submission", 636: "LDAPS", 853: "DNS over TLS", 993: "IMAPS", 995: "POP3S", 1433: "SQL Server", 1514: "Wazuh エージェント通信", 1515: "Wazuh エージェント登録",
  2049: "NFS", 2179: "Hyper-V VMConnect", 3268: "AD グローバルカタログ", 3306: "MySQL", 3389: "リモートデスクトップ（RDP）", 4500: "IPsec NAT-T", 5040: "Windows デバイス", 5353: "mDNS", 5355: "LLMNR",
  5357: "Web Services on Devices", 5432: "PostgreSQL", 5601: "ダッシュボード", 5900: "VNC", 5985: "WinRM（HTTP）", 5986: "WinRM（HTTPS）", 6379: "Redis", 7680: "Windows 配信最適化", 8080: "HTTP（代替）",
  8443: "HTTPS（代替）", 8444: "MamorAI", 9200: "Wazuh indexer / Elasticsearch", 11434: "Ollama", 27017: "MongoDB", 41641: "Tailscale", 55000: "Wazuh API",
};
const SYSTEM_LOGON = /^(SYSTEM|LOCAL SERVICE|NETWORK SERVICE|ANONYMOUS LOGON|DWM-\d+|UMFD-\d+|Font Driver Host|Window Manager|-|.*\$)$/i;
const ADMIN_GROUPS = /^(administrators|domain admins|enterprise admins|schema admins|sudo|wheel|admin|root)$/i;

function isPrivate(ip: string): boolean {
  return /^(10\.|127\.|169\.254\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|100\.(6[4-9]|[7-9]\d|1[01]\d|12[0-7])\.)/.test(ip) || /^(::1|fe80:|fc|fd)/i.test(ip);
}
function exposureOf(localIp: string, hasPublic: boolean): ListenFact["exposure"] {
  if (/^(127\.|::1$|localhost)/.test(localIp)) return "local";
  if (localIp === "0.0.0.0" || localIp === "::" || localIp === "*" || localIp === "") return hasPublic ? "internet" : "all";
  return isPrivate(localIp) ? "lan" : "internet";
}
const cap = <T>(arr: T[], n: number, limits: Record<string, string>, key: string): T[] => { if (arr.length > n) limits[key] = `${arr.length} 件中 ${n} 件`; return arr.slice(0, n); };

export async function collectFacts(ctx: Ctx, host: any): Promise<Facts> {
  const limits: Record<string, string> = {};
  const wid = host.wazuh_instance_id ?? (await ctx.db("wazuh_instances").orderBy("id").first())?.id;
  const facts: Facts = {
    version: 1, collected_at: new Date().toISOString(),
    host: { id: host.id, name: host.name, kind: host.kind ?? "managed", os_family: host.os_family ?? null, os: host.agent_os ?? null, agent_id: host.agent_id ?? null, agent_status: host.agent_status ?? null, agent_last_seen: host.agent_last_seen ? new Date(host.agent_last_seen).toISOString() : null, address: host.address, environment: host.environment },
    system: { ips: [], has_public_ip: false }, listening: [], services: [], services_total: 0,
    software: { total: 0, items: [], hotfixes: 0, latest_hotfixes: [], browser_extensions: [] },
    users: [], processes: [], processes_total: 0, connections: [], activity: { heatmap: Array.from({ length: 7 }, () => Array(24).fill(0)), total_7d: 0, top_rules: [] },
    vulns: { total: 0, by_severity: {}, top_packages: [] }, sca: [], limits,
  };
  if (host.agent_id && wid) {
    const ix = await indexer(ctx, wid);
    const ag = { term: { "agent.id": String(host.agent_id) } };
    const q = (index: string, size: number, extra: any = {}) => ix.search(`wazuh-states-inventory-${index}-*`, { query: { bool: { filter: [ag] } }, ...extra }, size).then((r: any) => (r.hits?.hits ?? []).map((h: any) => h._source)).catch(() => [] as any[]);
    const [sys, hw, nets, ports, procs, svcs, pkgs, hfx, exts, users, groups] = await Promise.all([
      q("system", 1), q("hardware", 1), q("networks", 100), q("ports", 500), q("processes", 500), q("services", 500), q("packages", 500), q("hotfixes", 500), q("browser-extensions", 200), q("users", 300), q("groups", 300),
    ]);
    // --- system
    const s0 = sys[0]?.host ?? {}, h0 = hw[0]?.host ?? {};
    const ips = [...new Set(nets.map((n: any) => String(n.network?.ip ?? "")).filter((ip: string) => ip && !/^(127\.|::1$|fe80:)/i.test(ip)))] as string[];
    facts.system = { hostname: s0.hostname ?? null, os: [s0.os?.name, s0.os?.version].filter(Boolean).join(" ") || null, kernel: s0.os?.kernel?.release ?? null, arch: s0.architecture ?? null, cpu: h0.cpu?.name ?? null, cores: h0.cpu?.cores ?? null, memory_gb: h0.memory?.total ? Math.round((h0.memory.total / 1024 ** 3) * 10) / 10 : null, serial: h0.serial_number ?? null, ips, has_public_ip: ips.some((ip) => !isPrivate(ip)) };
    if (!facts.host.os_family && s0.os?.platform) facts.host.os_family = String(s0.os.platform).toLowerCase().includes("windows") ? "windows" : "linux";
    // --- services (pid → service name, for Windows; Linux syscollector services are systemd units)
    const running = svcs.filter((x: any) => /^(running|active)$/i.test(String(x.service?.state ?? "")));
    const svcByPid = new Map<number, string>();
    for (const x of running) { const pid = Number(x.process?.pid ?? 0); if (pid > 0 && !svcByPid.has(pid)) svcByPid.set(pid, String(x.service?.name ?? x.service?.id)); }
    facts.services_total = svcs.length;
    facts.services = cap(running.map((x: any) => ({ id: `svc:${x.service?.name ?? x.service?.id}`, name: String(x.service?.name ?? x.service?.id ?? "?"), display: x.service?.description ?? x.service?.display_name ?? null, start_type: x.service?.start_type ?? null, state: String(x.service?.state ?? ""), pid: Number(x.process?.pid ?? 0) || null })), 150, limits, "services");
    // --- listening ports
    const seen = new Set<string>();
    for (const p of ports) {
      const st = String(p.interface?.state ?? "").toLowerCase(); const proto = String(p.network?.transport ?? "tcp").replace(/6$/, "");
      const lport = Number(p.source?.port ?? 0); if (!lport) continue;
      const isListen = st === "listening" || (proto === "udp" && Number(p.destination?.port ?? 0) === 0 && (!st || st === "unknown"));
      if (!isListen) continue;
      const lip = String(p.source?.ip ?? "");
      const key = `${proto}/${lport}/${lip}`; if (seen.has(key)) continue; seen.add(key);
      const pid = Number(p.process?.pid ?? 0) || null;
      facts.listening.push({ id: `port:${proto}/${lport}`, proto, port: lport, local_ip: lip, exposure: exposureOf(lip, facts.system.has_public_ip), process: p.process?.name ?? null, pid, service: pid ? svcByPid.get(pid) ?? null : null, known: WELL_KNOWN[lport] ?? null });
    }
    const expRank = { internet: 0, all: 1, lan: 2, local: 3 } as const;
    facts.listening.sort((a, b) => expRank[a.exposure] - expRank[b.exposure] || a.port - b.port);
    facts.listening = cap(facts.listening, 120, limits, "listening");
    // --- established connections (remote side)
    const conns = new Map<string, { ip: string; port: number | null; proc: string | null; n: number }>();
    for (const p of ports) {
      if (String(p.interface?.state ?? "").toLowerCase() !== "established") continue;
      const rip = String(p.destination?.ip ?? ""); if (!rip || /^(127\.|::1$|0\.0\.0\.0)/.test(rip)) continue;
      const k = `${rip}|${p.process?.name ?? ""}`; const c = conns.get(k) ?? { ip: rip, port: Number(p.destination?.port ?? 0) || null, proc: p.process?.name ?? null, n: 0 }; c.n++; conns.set(k, c);
    }
    facts.connections = cap([...conns.values()].sort((a, b) => b.n - a.n).map((c) => ({ id: `conn:${c.ip}`, remote_ip: c.ip, remote_port: c.port, process: c.proc, count: c.n })), 40, limits, "connections");
    // --- processes (grouped by name)
    const pm = new Map<string, { n: number; cmd: string | null }>();
    for (const p of procs) { const n = String(p.process?.name ?? ""); if (!n) continue; const e = pm.get(n) ?? { n: 0, cmd: null }; e.n++; if (!e.cmd && p.process?.command_line) e.cmd = String(p.process.command_line).slice(0, 200); pm.set(n, e); }
    facts.processes_total = procs.length;
    facts.processes = cap([...pm.entries()].sort((a, b) => b[1].n - a[1].n).map(([n, e]) => ({ id: `proc:${n}`, name: n, count: e.n, sample_cmd: e.cmd })), 80, limits, "processes");
    // --- software
    facts.software.total = pkgs.length;
    facts.software.items = cap(pkgs.map((p: any) => ({ id: `pkg:${p.package?.name}`, name: String(p.package?.name ?? "?"), version: p.package?.version ?? null, vendor: p.package?.vendor ?? null, installed: p.package?.installed ?? null })).sort((a: any, b: any) => String(b.installed ?? "").localeCompare(String(a.installed ?? ""))), 400, limits, "software");
    facts.software.hotfixes = hfx.length;
    facts.software.latest_hotfixes = hfx.map((h: any) => String(h.package?.hotfix?.name ?? "")).filter(Boolean).sort((a: string, b: string) => Number(b.replace(/\D/g, "")) - Number(a.replace(/\D/g, ""))).slice(0, 10);
    facts.software.browser_extensions = cap(exts.filter((e: any) => e.package?.name).map((e: any) => ({ id: `ext:${e.package.name}`, name: String(e.package.name), browser: e.browser?.name ?? null, version: e.package?.version ?? null, enabled: e.package?.enabled ?? null, from_store: e.package?.from_webstore ?? null })), 80, limits, "browser_extensions");
    // --- local accounts
    const adminGroupMembers = new Set<string>();
    for (const g of groups) if (ADMIN_GROUPS.test(String(g.group?.name ?? ""))) for (const u of g.group?.users ?? []) adminGroupMembers.add(String(u));
    facts.users = users.filter((u: any) => u.user?.name).map((u: any) => {
      const gs: string[] = Array.isArray(u.user?.groups) ? u.user.groups.map(String) : [];
      return { id: `user:${u.user.name}`, name: String(u.user.name), type: String(u.user?.type ?? "local"), admin: gs.some((g) => ADMIN_GROUPS.test(g)) || adminGroupMembers.has(String(u.user.name)) || Number(u.user?.id) === 0, groups: gs.slice(0, 10), shell: u.user?.shell ?? null, disabled: u.login?.status === false ? null : null };
    });
    // --- vulnerabilities
    try {
      const v = await ix.search("wazuh-states-vulnerabilities-*", { query: { bool: { filter: [ag] } }, aggs: { sev: { terms: { field: "vulnerability.severity", size: 6 } }, pk: { terms: { field: "package.name", size: 12 }, aggs: { c: { filter: { term: { "vulnerability.severity": "Critical" } } } } } } }, 0);
      facts.vulns = { total: v.hits?.total?.value ?? 0, by_severity: Object.fromEntries((v.aggregations?.sev?.buckets ?? []).map((b: any) => [b.key, b.doc_count])), top_packages: (v.aggregations?.pk?.buckets ?? []).map((b: any) => ({ name: b.key, count: b.doc_count, critical: b.c?.doc_count ?? 0 })) };
    } catch { limits.vulns = "取得できず"; }
    // --- alerts: activity heatmap (JST), top rules, logons
    const win7 = { range: { timestamp: { gte: "now-7d" } } };
    try {
      const a = await ix.search("wazuh-alerts-*", { query: { bool: { filter: [ag, win7] } }, aggs: { h: { date_histogram: { field: "timestamp", fixed_interval: "1h", min_doc_count: 1 } }, r: { terms: { field: "rule.id", size: 10 }, aggs: { d: { terms: { field: "rule.description", size: 1 } }, lv: { max: { field: "rule.level" } } } } } }, 0);
      facts.activity.total_7d = a.hits?.total?.value ?? 0;
      for (const b of a.aggregations?.h?.buckets ?? []) { const t = new Date(Number(b.key) + 9 * 3600_000); facts.activity.heatmap[t.getUTCDay()][t.getUTCHours()] += b.doc_count; }
      facts.activity.top_rules = (a.aggregations?.r?.buckets ?? []).map((b: any) => ({ id: String(b.key), description: b.d?.buckets?.[0]?.key ?? "", level: b.lv?.value ?? 0, count: b.doc_count }));
    } catch { limits.activity = "取得できず"; }
    const byUser = new Map<string, UserFact>();
    const userOf = (name: string) => { let u = facts.users.find((x) => x.name.toLowerCase() === name.toLowerCase()) ?? byUser.get(name.toLowerCase()); if (!u) { u = { id: `user:${name}`, name, type: name.includes("\\") ? "domain" : "seen_in_logs", admin: false, groups: [] }; byUser.set(name.toLowerCase(), u); } return u; };
    try { // Windows logons (Security 4624 success / 4625 failure)
      const l = await ix.search("wazuh-alerts-*", { query: { bool: { filter: [ag, win7, { terms: { "data.win.system.eventID": ["4624", "4625"] } }] } }, aggs: { u: { terms: { field: "data.win.eventdata.targetUserName", size: 60 }, aggs: { ev: { terms: { field: "data.win.system.eventID", size: 2 } }, lt: { terms: { field: "data.win.eventdata.logonType", size: 6 } }, ip: { terms: { field: "data.win.eventdata.ipAddress", size: 3 } }, last: { max: { field: "timestamp" } } } } } }, 0);
      for (const b of l.aggregations?.u?.buckets ?? []) {
        const name = String(b.key); if (SYSTEM_LOGON.test(name)) continue;
        const u = userOf(name); const ev = Object.fromEntries((b.ev?.buckets ?? []).map((x: any) => [String(x.key), x.doc_count]));
        u.logons_7d = (u.logons_7d ?? 0) + (ev["4624"] ?? 0); u.failures_7d = (u.failures_7d ?? 0) + (ev["4625"] ?? 0);
        u.logon_types = Object.fromEntries((b.lt?.buckets ?? []).map((x: any) => [String(x.key), x.doc_count]));
        u.sources = (b.ip?.buckets ?? []).map((x: any) => String(x.key)).filter((x: string) => x && x !== "-" && x !== "::1" && x !== "127.0.0.1");
        u.last_logon = b.last?.value_as_string ?? null;
      }
    } catch { /* not a Windows host / no Security log */ }
    try { // Linux / sshd / PAM logons
      const l = await ix.search("wazuh-alerts-*", { query: { bool: { filter: [ag, win7, { terms: { "rule.groups": ["authentication_success", "authentication_failed", "authentication_failures"] } }] } }, aggs: { u: { terms: { field: "data.dstuser", size: 40 }, aggs: { ok: { filter: { term: { "rule.groups": "authentication_success" } } }, ip: { terms: { field: "data.srcip", size: 3 } }, last: { max: { field: "timestamp" } } } } } }, 0);
      for (const b of l.aggregations?.u?.buckets ?? []) {
        const name = String(b.key); if (!name || SYSTEM_LOGON.test(name)) continue;
        const u = userOf(name); const ok = b.ok?.doc_count ?? 0;
        u.logons_7d = (u.logons_7d ?? 0) + ok; u.failures_7d = (u.failures_7d ?? 0) + (b.doc_count - ok);
        u.logon_types = { ...(u.logon_types ?? {}), ssh: ok }; u.sources = [...new Set([...(u.sources ?? []), ...(b.ip?.buckets ?? []).map((x: any) => String(x.key))])].slice(0, 3);
        u.last_logon = u.last_logon && u.last_logon > (b.last?.value_as_string ?? "") ? u.last_logon : b.last?.value_as_string ?? null;
      }
    } catch { /* no auth alerts */ }
    facts.users = [...facts.users, ...byUser.values()].sort((a, b) => (b.logons_7d ?? 0) - (a.logons_7d ?? 0) || Number(b.admin) - Number(a.admin) || a.name.localeCompare(b.name));
    facts.users = cap(facts.users, 80, limits, "users");
    // --- SCA
    try { const api = await managerApi(ctx, wid); const r: any = await api.get(`/sca/${encodeURIComponent(String(host.agent_id))}`); facts.sca = (r?.data?.affected_items ?? []).map((p: any) => ({ policy: String(p.name ?? p.policy_id), score: Number(p.score ?? 0), pass: Number(p.pass ?? 0), fail: Number(p.fail ?? 0) })); } catch { limits.sca = "取得できず"; }
  } else {
    limits.wazuh = host.agent_id ? "Wazuh インスタンス未設定" : "このホストには Wazuh エージェントが紐づいていません（編集でエージェント ID を設定）";
  }
  // --- SSH hosts: fixed read-only script
  if ((host.kind ?? "managed") === "managed" && host.ssh_key_id) {
    facts.ssh = await sshFacts(ctx, host);
    // no agent inventory → listening ports from `ss`
    if (!facts.listening.length) {
      const seen = new Set<string>();
      for (const l of facts.ssh.listen) { const k = `${l.proto}/${l.port}/${l.local_ip}`; if (seen.has(k)) continue; seen.add(k); facts.listening.push({ id: `port:${l.proto}/${l.port}`, ...l, exposure: exposureOf(l.local_ip, facts.system.has_public_ip), service: null, known: WELL_KNOWN[l.port] ?? null }); }
    }
    for (const a of facts.ssh.admins) { const u = facts.users.find((x) => x.name === a); if (u) u.admin = true; }
  }
  return facts;
}

export const SSH_SCAN_SCRIPT = [
  "echo '##SS'; ss -tulpnH 2>/dev/null | head -200",
  "echo '##UNITS'; systemctl list-units --type=service --state=running --no-pager --no-legend --plain 2>/dev/null | awk '{print $1}' | head -200",
  "echo '##WHO'; who 2>/dev/null | head -30",
  "echo '##LAST'; last -n 40 -F -w 2>/dev/null | grep -v '^$' | head -40",
  "echo '##ADM'; getent group sudo wheel admin 2>/dev/null",
  "echo '##CRON'; for f in /etc/crontab /etc/cron.d/*; do [ -f \"$f\" ] && grep -hvE '^\\s*(#|$|[A-Z_]+=)' \"$f\" | sed \"s|^|$f: |\"; done 2>/dev/null | head -40; for u in $(awk -F: '$7 !~ /(nologin|false|sync|halt|shutdown)$/ {print $1}' /etc/passwd); do crontab -l -u \"$u\" 2>/dev/null | grep -vE '^\\s*(#|$)' | sed \"s|^|crontab($u): |\"; done | head -40",
  "echo '##TIMERS'; systemctl list-timers --all --no-pager --no-legend 2>/dev/null | awk '{print $(NF-1)}' | head -40",
  "echo '##DOCKER'; command -v docker >/dev/null 2>&1 && docker ps --format '{{.Names}}|{{.Image}}|{{.Ports}}' 2>/dev/null | head -40",
  "echo '##WEB'; (command -v apachectl >/dev/null 2>&1 && apachectl -S 2>/dev/null | grep -E 'namevhost|port [0-9]+ ' | head -30); (command -v nginx >/dev/null 2>&1 && nginx -T 2>/dev/null | grep -E '^\\s*server_name' | sort -u | head -30)",
  "echo '##PACK'; head -c 2000 /etc/mamorai/pack.json 2>/dev/null | tr -d '\\n'; echo",
  "echo '##END'",
].join("\n");

async function sshFacts(ctx: Ctx, host: any): Promise<NonNullable<Facts["ssh"]>> {
  const empty = { listen: [], units: [], logged_in: [], last_logins: [], cron: [], timers: [], containers: [], web: [], admins: [] };
  try {
    const key = await ctx.db("ssh_keys").where({ id: host.ssh_key_id }).first();
    const r = await sshExec({ address: host.address, port: host.port, user: host.ssh_user, privateKey: ctx.box.decrypt(key.private_key_enc), sudoMode: host.sudo_mode, hostKey: host.host_key }, SSH_SCAN_SCRIPT, 60_000);
    const sec = (name: string) => { const m = r.stdout.split(`##${name}\n`)[1]; return (m ?? "").split(/\n##[A-Z]+\n?/)[0].split("\n").map((l) => l.trim()).filter(Boolean); };
    const units = sec("UNITS").filter((u) => u.endsWith(".service")).map((u) => ({ id: `unit:${u.replace(/\.service$/, "")}`, name: u.replace(/\.service$/, "") }));
    const cron = sec("CRON").slice(0, 60).map((line, i) => ({ id: `cron:${i + 1}`, line: line.slice(0, 220) }));
    const containers = sec("DOCKER").map((l) => { const [name, image, ports] = l.split("|"); return { id: `ctr:${name}`, name, image: image ?? "", ports: ports ?? "" }; });
    const listen = sec("SS").map((l) => {
      const f = l.split(/\s+/); const proto = (f[0] ?? "tcp").replace(/6$/, ""); const local = f[4] ?? ""; const i = local.lastIndexOf(":");
      const ip = local.slice(0, i).replace(/^\[|\]$/g, "").replace(/%.*$/, ""); const port = Number(local.slice(i + 1));
      const pm = l.match(/users:\(\("([^"]+)",pid=(\d+)/);
      return { proto, port, local_ip: ip === "*" ? "0.0.0.0" : ip, process: pm?.[1] ?? null, pid: pm ? Number(pm[2]) : null };
    }).filter((x) => x.port > 0);
    const admins = sec("ADM").flatMap((l) => (l.split(":")[3] ?? "").split(",")).map((x) => x.trim()).filter(Boolean);
    const pm2 = sec("PACK").join("").match(/"rev"\s*:\s*(\d{1,6})/); // EDR-130: agent pack revision installed by install-edr-agent-linux.sh
    return { ok: r.code === 0, error: r.code === 0 ? undefined : r.stderr.slice(0, 300), listen, units, logged_in: sec("WHO"), last_logins: sec("LAST"), cron, timers: sec("TIMERS"), containers, web: sec("WEB"), admins: [...new Set(admins)], pack_rev: pm2 ? Number(pm2[1]) : null };
  } catch (e: any) {
    return { ok: false, error: String(e.message ?? e).slice(0, 300), ...empty };
  }
}
